import base64
import os
from dataclasses import dataclass
from typing import Dict, Optional, Tuple

import boto3
from botocore.exceptions import BotoCoreError, ClientError
from cryptography.hazmat.primitives.ciphers.aead import AESGCM


@dataclass(frozen=True)
class EnvelopeCiphertext:
    encrypted_data_key_b64: str
    nonce_b64: str
    ciphertext_b64: str
    kms_key_id: str

    def to_dict(self) -> Dict[str, str]:
        return {
            "encrypted_data_key_b64": self.encrypted_data_key_b64,
            "nonce_b64": self.nonce_b64,
            "ciphertext_b64": self.ciphertext_b64,
            "kms_key_id": self.kms_key_id,
        }

    @staticmethod
    def from_dict(payload: Dict[str, str]) -> "EnvelopeCiphertext":
        return EnvelopeCiphertext(
            encrypted_data_key_b64=payload["encrypted_data_key_b64"],
            nonce_b64=payload["nonce_b64"],
            ciphertext_b64=payload["ciphertext_b64"],
            kms_key_id=payload["kms_key_id"],
        )


class AWSEnvelopeEncryption:
    """
    Envelope encryption using AWS KMS:
      1) Generate a random data key locally.
      2) Use AWS KMS Encrypt to wrap the data key.
      3) Use AES-GCM to encrypt plaintext with the data key.
      4) Store wrapped key + nonce + ciphertext.
    """

    def __init__(self, kms_key_id: Optional[str] = None, region_name: Optional[str] = None):
        self.kms_key_id = kms_key_id or os.environ.get("AWS_KMS_KEY_ID")
        if not self.kms_key_id:
            raise ValueError("Missing AWS KMS key id. Set AWS_KMS_KEY_ID or pass kms_key_id.")

        self.kms_client = boto3.client("kms", region_name=region_name)

    def encrypt(self, plaintext: bytes, encryption_context: Optional[Dict[str, str]] = None) -> EnvelopeCiphertext:
        if not isinstance(plaintext, (bytes, bytearray)):
            raise TypeError("plaintext must be bytes")

        data_key = AESGCM.generate_key(bit_length=256)
        try:
            kms_resp = self.kms_client.encrypt(
                KeyId=self.kms_key_id,
                Plaintext=data_key,
                EncryptionContext=encryption_context or {},
            )
            encrypted_data_key = kms_resp["CiphertextBlob"]
        except (BotoCoreError, ClientError) as exc:
            raise RuntimeError(f"AWS KMS encrypt failed: {exc}") from exc

        aesgcm = AESGCM(data_key)
        nonce = os.urandom(12)
        aad = self._aad_bytes(encryption_context)
        ciphertext = aesgcm.encrypt(nonce, bytes(plaintext), aad)

        return EnvelopeCiphertext(
            encrypted_data_key_b64=base64.b64encode(encrypted_data_key).decode("utf-8"),
            nonce_b64=base64.b64encode(nonce).decode("utf-8"),
            ciphertext_b64=base64.b64encode(ciphertext).decode("utf-8"),
            kms_key_id=self.kms_key_id,
        )

    def decrypt(self, envelope: EnvelopeCiphertext, encryption_context: Optional[Dict[str, str]] = None) -> bytes:
        if not isinstance(envelope, EnvelopeCiphertext):
            raise TypeError("envelope must be an EnvelopeCiphertext instance")

        encrypted_data_key = base64.b64decode(envelope.encrypted_data_key_b64)
        nonce = base64.b64decode(envelope.nonce_b64)
        ciphertext = base64.b64decode(envelope.ciphertext_b64)

        try:
            kms_resp = self.kms_client.decrypt(
                CiphertextBlob=encrypted_data_key,
                EncryptionContext=encryption_context or {},
            )
            data_key = kms_resp["Plaintext"]
        except (BotoCoreError, ClientError) as exc:
            raise RuntimeError(f"AWS KMS decrypt failed: {exc}") from exc

        aesgcm = AESGCM(data_key)
        aad = self._aad_bytes(encryption_context)
        return aesgcm.decrypt(nonce, ciphertext, aad)

    @staticmethod
    def _aad_bytes(encryption_context: Optional[Dict[str, str]]) -> bytes:
        if not encryption_context:
            return b""
        items = sorted((str(k), str(v)) for k, v in encryption_context.items())
        return "&".join(f"{k}={v}" for k, v in items).encode("utf-8")
